		$output .= '.dtsl-listings-nearby-places-container .dtsl-listings-nearby-places-item:not(:last-child), .dtsl-listings-author-container .dtsl-listings-author-details-holder, .dtsl-packages-item-wrapper.type2 .dtsl-packagelist-details, #primary.page-with-sidebar .dtsl-packages-item-wrapper.type2 .dtsl-packagelist-details, .dtsl-listings-features-box-container:not(.listing).type7 .dtsl-listings-features-box-item, .dtsl-listings-item-wrapper.type11 { border-color:'.$tertiary_color.'}';

		// Single Page Shortcode Border Color Ends

		$output .= '.dtsl-user-list-item.type3 .dtsl-user-contactdetails-list li span, .dtsl-listings-author-container .dtsl-listings-author-details-holder .dtsl-listings-author-details .dtsl-listings-contactdetails-list li span { box-shadow: inset 0 0 0 2px '.$tertiary_color.' }';

		// RGBA Colors

		$output .= '.dtsl-listings-media-videos-container.swiper-container div[class*="dtsl-swiper-arrow-pagination"].type2 > a[class*="dtsl-swiper-arrow"] { background-color:rgba('.$primary_color_rgba.', 0.5)}';

		$output .= '.dtsl-listings-media-videos-container.swiper-container div[class*="dtsl-swiper-arrow-pagination"].type2>a[class*="dtsl-swiper-arrow"]:hover, .dtsl-listings-image-gallery-container.swiper-container div[class*="dtsl-swiper-arrow-pagination"].type2>a[class*="dtsl-swiper-arrow"]:hover { background-color:rgba('.$primary_color_rgba.', 0.6)}';

		$output .= '.dtsl-listings-image-gallery-container.swiper-container div[class*="dtsl-swiper-arrow-pagination"].type2>a[class*="dtsl-swiper-arrow"] { background-color:rgba('.$primary_color_rgba.', 0.15)}';

		$output .= '.lidd_mc_details .lidd_mc_summary p:not(:last-child), .lidd_mc_details .lidd_mc_results p, .dtsl-listing-taxonomy-item.type4:hover, .dtsl-listing-taxonomy-item.type4:hover .dtsl-listing-taxonomy-starting-price, .dtsl-user-list-item.type2 .dtsl-user-image img, .dtsl-dashbord-section-holder-content ul.dtsl-dashbord-inbox-listing-messages-wrapper li:hover span, .dtsl-dashbord-section-holder-content ul.dtsl-dashbord-inbox-listing-messages-wrapper li.active span { border-color:rgba('.$secondary_color_rgba.', 0.2)}';

		$output .= '.dtsl-dashbord-container .dtsl-packages-container .dtsl-packages-item-wrapper:hover, .dtsl-dashbord-container .dtsl-my-listings-container .dtsl-listing-item-wrapper:hover { background-color:rgba('.$tertiary_color_rgba.', 0.135)}';

		$output .= '.lidd_mc_details, .dtsl-listing-taxonomy-item.type4:hover, .dtsl-listings-nearby-places-container:hover .dtsl-listings-nearby-places-item .dtsl-listings-nearby-places-image { background-color:rgba('.$tertiary_color_rgba.', 0.5)}';

		// Listing Toggle Skin

		$output .= '.dtsl-toggle-container.type4 > .dtsl-toggle > .dtsl-toggle-group > .dtsl-toggle-content { background-color:'.$tertiary_color.'}';

		$output .= '.dtsl-toggle-container.type2 > .dtsl-toggle > .dtsl-toggle-group > .dtsl-toggle-title:hover,
		.dtsl-toggle-container.type2 > .dtsl-toggle > .dtsl-toggle-group > .dtsl-toggle-title.active,
		.dtsl-toggle-container.type2 > .dtsl-toggle > .dtsl-toggle-group:last-child >.dtsl-toggle-title.active,		
		.dtsl-toggle-container.type4 > .dtsl-toggle > .dtsl-toggle-group:not(:last-child) { border-color:'.$tertiary_color.'}';

		wp_register_style ( 'dtsl-skin', false );
		wp_add_inline_style( 'dtsl-skin', $output );

		wp_enqueue_style ( 'dtsl-skin' );

	}

	add_action( 'wp_enqueue_scripts', 'dtsl_generate_skin_colors', 140 );

}

